// Block (composition) — multi-step orchestration with progress and navigation.
// Arranges only; composes ProgressBar/Button/Stack.
import { useCallback, useEffect, useId, useRef, useState } from "react";
import type { ReactNode, Ref } from "react";
import { ProgressBar } from "../components/ProgressBar";
import { Button } from "../components/Button";
import { Stack } from "../layouts/Stack";
import "./Wizard.css";

export interface WizardProps {
  steps: { title: string; content: ReactNode }[];
  /** The current step, controlled. Pair with `onStepChange`; omit both to let the wizard keep it. */
  stepIndex?: number;
  /** The step the wizard opens on when it keeps its own state. @default 0 */
  defaultStepIndex?: number;
  /** Called with the step Back or Next moves to. */
  onStepChange?: (index: number) => void;
  onComplete?: () => void;
  completeLabel?: string;
  backLabel?: string;
  nextLabel?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function Wizard({
  steps,
  stepIndex: controlledIndex,
  defaultStepIndex = 0,
  onStepChange,
  onComplete,
  completeLabel = "Finish",
  backLabel = "Back",
  nextLabel = "Next",
  className,
  ref,
}: WizardProps) {
  const titleId = useId();
  const titleRef = useRef<HTMLHeadingElement>(null);
  const shownIndex = useRef<number | null>(null);
  // Controlled when `stepIndex` is given, the React Aria convention for a value with an onChange.
  const [ownIndex, setOwnIndex] = useState(defaultStepIndex);
  const stepIndex = controlledIndex ?? ownIndex;
  const setStepIndex = (index: number) => {
    if (controlledIndex === undefined) setOwnIndex(index);
    onStepChange?.(index);
  };

  /* A step reached from outside the wizard (a checklist beside it, a link) leaves focus wherever the
     jump started, often on a control that the jump just removed. So when the step changes and focus is
     not inside the wizard, it goes to the new step's title, as a multi-page form moves it to the page
     heading. Back and Next keep focus where it is. */
  const sectionRef = useRef<HTMLElement | null>(null);
  // One stable callback for the internal node and the caller's ref, keeping a cleanup the caller's
  // callback returns (React 19), the pattern ScrollArea states in full.
  const attach = useCallback(
    (node: HTMLElement | null) => {
      sectionRef.current = node;
      if (typeof ref === "function") {
        const cleanup = ref(node);
        return () => {
          sectionRef.current = null;
          if (typeof cleanup === "function") cleanup();
          else ref(null);
        };
      }
      if (ref) ref.current = node;
      return () => {
        sectionRef.current = null;
        if (ref) ref.current = null;
      };
    },
    [ref],
  );
  useEffect(() => {
    const index = Math.max(0, Math.min(Math.trunc(controlledIndex ?? ownIndex) || 0, steps.length - 1));
    if (shownIndex.current !== null && shownIndex.current !== index && !sectionRef.current?.contains(document.activeElement))
      titleRef.current?.focus();
    shownIndex.current = index;
  });

  if (steps.length === 0) return null;

  // Any index lands on a real step: a negative, fractional or NaN one would otherwise index nothing.
  const currentIndex = Math.max(0, Math.min(Math.trunc(stepIndex) || 0, steps.length - 1));
  const currentStep = steps[currentIndex];
  const isLastStep = currentIndex === steps.length - 1;

  const handleNext = () => {
    if (isLastStep) {
      onComplete?.();
      return;
    }
    setStepIndex(currentIndex + 1);
  };

  return (
    <section
      ref={attach}
      aria-labelledby={titleId}
      className={className ? `sd-wizard ${className}` : "sd-wizard"}
    >
      <Stack gap="large" className="sd-wizard__body">
        <ProgressBar
          value={((currentIndex + 1) / steps.length) * 100}
          aria-label={currentStep.title}
        />
        {/* spacing: attachment — the progress bar heads the step it measures */}
        <Stack gap="medium" className="sd-wizard__step">
          <>
            <h2 id={titleId} ref={titleRef} tabIndex={-1} className="sd-wizard__title sd-type-title-medium">{currentStep.title}</h2>
          </>
          <div className="sd-wizard__content">{currentStep.content}</div>
        </Stack>
        {/* usage: completing-action — Next ends each step and, on the last, the wizard; Back shares its row */}
        <Stack direction="row" gap="small" justify="between" className="sd-wizard__actions">
          <Button
            type="button"
            variant="secondary"
            size="large"
            isDisabled={currentIndex === 0}
            onPress={() => setStepIndex(currentIndex - 1)}
          >
            {backLabel}
          </Button>
          <Button type="button" variant="primary" size="large" onPress={handleNext}>
            {isLastStep ? completeLabel : nextLabel}
          </Button>
        </Stack>
      </Stack>
    </section>
  );
}

/* Wizard.css — arrangement only; Component look stays with its owners. */
/* A Panel (block-contract § 1b): it fills its parent, which owns the width. */
.sd-wizard {
  width: 100%;
}

.sd-wizard__title {
  margin: 0;
}

/* The title takes focus only when a step is reached from outside the wizard, as a landing point for a
   screen reader. It is not a tab stop and not a control, so it draws no focus indicator. */
.sd-wizard__title {
  outline: none;
}
